// A small enum for the two regions
#[derive(Copy, Clone, PartialEq)]
enum Region {
    A, // x > y
    B, // y > x
}

fn solve(n: i8, s: Vec<char>) -> i8 {
    let mut x: i8 = 0;
    let mut y: i8 = 0;
    let mut last_region: Option<Region> = None;
    let mut transitions: i8 = 0;

    for &c in &s {
        // apply the move
        match c {
            'U' => y += 1,
            'R' => x += 1,
            _   => (), // ignore any other chars, though per spec there are none
        }

        // figure out which region (if any) we're in now
        let curr = if x > y {
            Some(Region::A)
        } else if y > x {
            Some(Region::B)
        } else {
            None  // on the diagonal = border
        };

        // if we're strictly in A or B,
        // compare to last_region (if any) to count a transition
        if let Some(region) = curr {
            if let Some(prev) = last_region {
                if region != prev {
                    transitions += 1;
                }
            }
            // update the last non‐border region
            last_region = Some(region);
        }
    }

    transitions
}